import re

def entities(doc, scope):
    """Extracts all distinct entities (machines, tasks, jobs) mentioned in the scope."""
    scope_node = node_by_title(doc, scope)
    nodes = scope_nodes(doc, scope_node)

    ents = {}

    # Extract machines
    machines_node = next((n for n in nodes if n['title'] == f"{scope}: Machines"), None)
    if machines_node:
        for _, row in table_rows(machines_node):
            m_id = row['machine']
            ents[m_id] = f"Machine {m_id}"

    # Extract tasks and jobs
    task_log_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if task_log_node:
        for _, row in table_rows(task_log_node):
            t_id = row['task']
            ents[t_id] = f"Task {t_id}"
            j_id = row['job']
            ents[j_id] = f"Job {j_id}"

    return [{"id": eid, "description": desc} for eid, desc in ents.items()]

def recorded_end(doc, scope):
    """The last time point covered by the scope's records (always 1200 in this dataset)."""
    return 1200.0

def inputs(doc, scope):
    """Everything that enters the process from outside (machine specs, fail/return times, task submissions)."""
    scope_node = node_by_title(doc, scope)
    nodes = scope_nodes(doc, scope_node)
    inputs_list = []
    input_id_counter = 0

    # Machine specs and scheduled failures/returns
    machines_node = next((n for n in nodes if n['title'] == f"{scope}: Machines"), None)
    if machines_node:
        for row_idx, row in table_rows(machines_node):
            m_id = row['machine']
            # Machine capacity input
            inputs_list.append({
                "id": f"in_m_spec_{m_id}",
                "time": 0.0,
                "kind": "machine_spec",
                "entities": [m_id],
                "fields": {"CPU": int(row['CPU']), "memory": int(row['memory'])},
                "src": [machines_node['node_id'], row_idx]
            })
            # Scheduled failure
            if row['fails at'] != '-':
                input_id_counter += 1
                inputs_list.append({
                    "id": f"in_m_fail_{input_id_counter}",
                    "time": float(row['fails at']),
                    "kind": "machine_failure",
                    "entities": [m_id],
                    "fields": {},
                    "src": [machines_node['node_id'], row_idx]
                })
            # Scheduled return
            if row['returns at'] != '-' and row['returns at'] != 'never':
                input_id_counter += 1
                inputs_list.append({
                    "id": f"in_m_ret_{input_id_counter}",
                    "time": float(row['returns at']),
                    "kind": "machine_return",
                    "entities": [m_id],
                    "fields": {},
                    "src": [machines_node['node_id'], row_idx]
                })

    # Task submissions
    task_log_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if task_log_node:
        for row_idx, row in table_rows(task_log_node):
            if row['event'] == 'submit':
                t_id = row['task']
                inputs_list.append({
                    "id": f"in_t_sub_{t_id}",
                    "time": float(row['time']),
                    "kind": "task_submission",
                    "entities": [t_id, row['job']],
                    "fields": {
                        "priority": int(row['priority']),
                        "CPU": int(row['CPU']),
                        "memory": int(row['memory']),
                        "run_time": int(row['run time'])
                    },
                    "src": [task_log_node['node_id'], row_idx]
                })

    return inputs_list

def outcomes(doc, scope):
    """Everything the process produces (starts, finishes, evictions, failures, queue state)."""
    scope_node = node_by_title(doc, scope)
    nodes = scope_nodes(doc, scope_node)
    outcomes_list = []

    # Log events (start, finish, evict, fail)
    task_log_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if task_log_node:
        for row_idx, row in table_rows(task_log_node):
            event = row['event']
            if event in ['start', 'finish', 'evict', 'fail']:
                t_id = row['task']
                m_id = row['machine']
                entities = [t_id]
                if m_id != '-':
                    entities.append(m_id)

                outcomes_list.append({
                    "time": float(row['time']),
                    "kind": f"task_{event}",
                    "entities": entities,
                    "value": None,
                    "src": [task_log_node['node_id'], row_idx]
                })

    # Longest waits from Events list
    events_node = next((n for n in nodes if n['title'] == f"{scope}: Events"), None)
    if events_node:
        for line_idx, line in enumerate(events_node['lines']):
            # Looking for "longest wait was X seconds" or similar patterns
            match = re.search(r"longest wait.*? (\d+) second", line)
            if match:
                wait_val = int(match.group(1))
                # This is a computed result, often associated with a task or the cell
                outcomes_list.append({
                    "time": 1200.0, # These are usually reported at the end
                    "kind": "longest_wait",
                    "entities": [],
                    "value": wait_val,
                    "src": [events_node['node_id'], line_idx]
                })

    # State at window end
    queue_node = next((n for n in nodes if n['title'] == f"{scope}: Queue at window end"), None)
    if queue_node:
        for row_idx, row in table_rows(queue_node):
            t_id = row['task']
            # Remaining run time is a computed value
            if row['remaining'] != '-':
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "remaining_run_time",
                    "entities": [t_id],
                    "value": int(row['remaining']),
                    "src": [queue_node['node_id'], row_idx]
                })
            # Started time is a result of the scheduling process
            if row['started'] != '-':
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "start_time",
                    "entities": [t_id],
                    "value": int(row['started']),
                    "src": [queue_node['node_id'], row_idx]
                })

    return outcomes_list

def params(doc, scope):
    """Constants defined in the document."""
    return {
        "window_length": 1200
    }

